/* Proper alias-root observations: close ONLY the clean upper DBI; every
 * separate DUPFIXED tree uses one consistent width; no dirty/closed reuse. */
#define _GNU_SOURCE
#include <lmdb.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
static void need(int b,const char*s){if(!b){fprintf(stderr,"fatal %s\n",s);exit(2);}}
static void ok(int rc,const char*s){if(rc){fprintf(stderr,"fatal %s rc=%d %s\n",s,rc,mdb_strerror(rc));exit(2);}}
static int lexical(const MDB_val*a,const MDB_val*b){size_t n=a->mv_size<b->mv_size?a->mv_size:b->mv_size;int c=memcmp(a->mv_data,b->mv_data,n);return c?c:(a->mv_size>b->mv_size)-(a->mv_size<b->mv_size);}
static int fold(const MDB_val*a,const MDB_val*b){size_t n=a->mv_size<b->mv_size?a->mv_size:b->mv_size;for(size_t i=0;i<n;i++){unsigned char x=((unsigned char*)a->mv_data)[i],y=((unsigned char*)b->mv_data)[i];if(x>='A'&&x<='Z')x+=32;if(y>='A'&&y<='Z')y+=32;if(x!=y)return(x>y)-(x<y);}return(a->mv_size>b->mv_size)-(a->mv_size<b->mv_size);}
static MDB_val val(const char*s){return(MDB_val){strlen(s),(void*)s};}
static MDB_env*env(const char*p,unsigned f){MDB_env*e;ok(mdb_env_create(&e),"env create");ok(mdb_env_set_maxdbs(e,12),"maxdbs");ok(mdb_env_set_mapsize(e,16u*1024u*1024u),"mapsize");ok(mdb_env_open(e,p,f|MDB_NOTLS,0600),"env open");return e;}
static MDB_txn*begin(MDB_env*e,unsigned f){MDB_txn*t;ok(mdb_txn_begin(e,NULL,f,&t),"begin");return t;}
static MDB_dbi main_db(MDB_txn*t){MDB_dbi d;ok(mdb_dbi_open(t,NULL,0,&d),"MAIN open");ok(mdb_set_compare(t,d,fold),"MAIN comparator before named/data access");return d;}
static void hex(const void*p,size_t n){const unsigned char*b=p;for(size_t i=0;i<n;i++)printf("%02x",b[i]);}
static int put(MDB_txn*t,MDB_dbi d,const char*k,const char*v,const char*label){MDB_val key=val(k),value=val(v);int rc=mdb_put(t,d,&key,&value,0);printf("%s.rc=%d size=%zu\n",label,rc,value.mv_size);return rc;}
static int flags(MDB_txn*t,MDB_dbi d,const char*label){unsigned f=~0u;int rc=mdb_dbi_flags(t,d,&f);printf("%s.flags.rc=%d flags=%u\n",label,rc,f);return rc;}
static int dump(MDB_txn*t,MDB_dbi d,const char*label){MDB_cursor*c=NULL;int rc=mdb_cursor_open(t,d,&c);printf("%s.cursor_open.rc=%d\n",label,rc);if(rc)return rc;MDB_val k={0,NULL},v={0,NULL};rc=mdb_cursor_get(c,&k,&v,MDB_FIRST);unsigned n=0;while(!rc){need(n<32,"bounded row count");printf("%s.row%u.key=",label,n++);hex(k.mv_data,k.mv_size);printf(" size=%zu value=",v.mv_size);hex(v.mv_data,v.mv_size);putchar('\n');rc=mdb_cursor_get(c,&k,&v,MDB_NEXT);}printf("%s.end.rc=%d rows=%u\n",label,rc,n);mdb_cursor_close(c);return rc;}
static void show(MDB_txn*t,MDB_dbi d,const char*label){(void)flags(t,d,label);(void)dump(t,d,label);}
static int write_upper(MDB_txn*t,MDB_dbi d){int rc=put(t,d,"k","nnnn","upper.put");if(!rc)rc=put(t,d,"q","QQQQ","upper.extra");return rc;}
static int write_lower(MDB_txn*t,MDB_dbi d){int rc=put(t,d,"k","llllllll","lower.put");if(!rc)rc=put(t,d,"l","LLLLLLLL","lower.extra");return rc;}
static void fresh(MDB_env*e,const char*label,int callbacks){MDB_txn*t=begin(e,MDB_RDONLY);(void)main_db(t);MDB_dbi l=0,u=0;int lr=mdb_dbi_open(t,"x",0,&l),ur=mdb_dbi_open(t,"X",0,&u);printf("%s.open.lower=%d upper=%d distinct=%d\n",label,lr,ur,!lr&&!ur&&l!=u);if(callbacks){if(!lr)ok(mdb_set_compare(t,l,lexical),"fresh lower comparator before access");if(!ur)ok(mdb_set_compare(t,u,lexical),"fresh upper comparator before access");}char text[96];if(!lr){snprintf(text,sizeof text,"%s.lower",label);show(t,l,text);}if(!ur){snprintf(text,sizeof text,"%s.upper",label);show(t,u,text);}mdb_txn_abort(t);}
int main(int argc,char**argv){setvbuf(stdout,NULL,_IONBF,0);Dl_info provider;need(dladdr((void*)mdb_env_open,&provider)&&provider.dli_fname,"provider");fprintf(stderr,"PROVIDER %s\n",provider.dli_fname);if(argc!=3)return 2;int mode=atoi(argv[1]);need(mode>=0&&mode<9,"case range");int kind=mode/3,order=mode%3;unsigned oldflags=kind==0?0:MDB_DUPSORT|(kind==2?MDB_DUPFIXED:0);unsigned newflags=kind==1?0:MDB_DUPSORT|(kind==2?MDB_DUPFIXED:0);printf("case=%d kind=%d order=%d oldflags=%u newflags=%u oldwidth=8 newwidth=4\n",mode,kind,order,oldflags,newflags);const char*path=argv[2];need(!mkdir(path,0700),"fresh database");MDB_env*e=env(path,0);MDB_txn*t=begin(e,0);(void)main_db(t);MDB_dbi upper,lower;ok(mdb_dbi_open(t,"X",MDB_CREATE|oldflags,&upper),"seed X");ok(mdb_set_compare(t,upper,lexical),"seed comparator before data");ok(put(t,upper,"k","bbbbbbbb","seed.put"),"seed put");ok(mdb_txn_commit(t),"seed commit");
 t=begin(e,MDB_RDONLY);(void)main_db(t);ok(mdb_dbi_open(t,"x",0,&lower),"export lower");ok(mdb_set_compare(t,lower,lexical),"lower comparator before access");ok(mdb_dbi_open(t,"X",0,&upper),"export upper");need(lower!=upper,"distinct public alias identities");ok(mdb_txn_commit(t),"export aliases");
 t=begin(e,0);MDB_dbi main=main_db(t);ok(mdb_dbi_open(t,"x",0,&lower),"writer lower");ok(mdb_dbi_open(t,"X",0,&upper),"writer upper");printf("ids.lower=%u upper=%u\n",lower,upper);show(t,lower,"preload.lower");show(t,upper,"preload.upper");MDB_cursor*held;ok(mdb_cursor_open(t,lower,&held),"held lower cursor");MDB_val k=val("k"),v;ok(mdb_cursor_get(held,&k,&v,MDB_SET),"position old lower");int clear=mdb_drop(t,main,0);printf("main.clear.rc=%d\n",clear);
 /* Neither named alias has been modified, and there is no upper cursor. */
 mdb_dbi_close(e,upper);puts("old.upper.clean_closed=1");MDB_dbi replacement=0;int opened=mdb_dbi_open(t,"X",MDB_CREATE|newflags,&replacement);printf("new.upper.open.rc=%d id=%u\n",opened,replacement);if(opened){puts("boundary=replacement-open-rejected");mdb_cursor_close(held);mdb_txn_abort(t);mdb_env_close(e);puts("kind-recreate-observation-complete");return 0;}need(replacement!=lower,"fresh output distinct from loaded lower");ok(mdb_set_compare(t,replacement,lexical),"replacement comparator before access");show(t,replacement,"new.upper.before");show(t,lower,"old.lower.before");
 if(clear){printf("boundary=MAIN-clear-rejected rc=%d; no new-kind/width writes attempted\n",clear);mdb_cursor_close(held);mdb_txn_abort(t);mdb_env_close(e);puts("kind-recreate-observation-complete");return 0;}
 int rc=0;if(order==1)rc=write_lower(t,lower);if(!rc)rc=write_upper(t,replacement);if(!rc&&order==0)rc=write_lower(t,lower);if(rc){printf("boundary=named-put-rejected rc=%d; abort-without-reuse\n",rc);mdb_cursor_close(held);mdb_txn_abort(t);mdb_env_close(e);puts("kind-recreate-observation-complete");return 0;}
 show(t,lower,"writer.lower");show(t,replacement,"writer.upper");k=(MDB_val){0,NULL};v=(MDB_val){0,NULL};rc=mdb_cursor_get(held,&k,&v,MDB_GET_CURRENT);printf("held.lower.current.rc=%d",rc);if(!rc){printf(" size=%zu value=",v.mv_size);hex(v.mv_data,v.mv_size);}putchar('\n');mdb_cursor_close(held);rc=mdb_txn_commit(t);printf("outer.commit.rc=%d\n",rc);if(!rc)fresh(e,"fresh",0);mdb_env_close(e);if(!rc){e=env(path,MDB_RDONLY);fresh(e,"reopen",1);mdb_env_close(e);}puts("kind-recreate-observation-complete");return 0;
}
